// Node: "Prepare Candidate"  (Code, Run Once for All Items)
// Normalises the Gmail Trigger output into a stable shape and decides whether
// the email is worth treating as an invoice candidate at all.
//
// Gmail Trigger with Simplify=OFF parses mail with mailparser, so `from` is an
// object ({ value: [{ address, name }], text, html }), NOT a string, and the
// body lives under text / html / textAsHtml. Both shapes are handled defensively.

const KEYWORDS =
  /\b(invoice|invoices|invoicing|billing|bill|payment|receipt|statement|fee note|charges|factuur)\b/i;

function extractEmail(raw) {
  if (!raw) return '';
  if (typeof raw === 'string') {
    const m = raw.match(/<([^>]+)>/);
    return (m ? m[1] : raw).trim().toLowerCase();
  }
  if (Array.isArray(raw.value) && raw.value[0] && raw.value[0].address) {
    return String(raw.value[0].address).trim().toLowerCase();
  }
  if (raw.address) return String(raw.address).trim().toLowerCase();
  if (raw.text) {
    const m = String(raw.text).match(/<([^>]+)>/);
    return (m ? m[1] : raw.text).trim().toLowerCase();
  }
  return '';
}

function htmlToText(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

function toIso(value) {
  if (!value) return new Date().toISOString();
  const d = new Date(value);
  return isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
}

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const binary = item.binary || {};

  const subject = String(j.subject || '').trim();
  const senderEmail = extractEmail(j.from);

  const plain = String(j.text || '').trim();
  const emailBody = plain || htmlToText(j.html || j.textAsHtml || '');

  // j.id is the Gmail API message id; j.messageId is the RFC-822 header. Prefer the API id.
  const gmailMessageId = String(j.id || j.messageId || '').trim();

  // Collect EVERY PDF, not just the first. One email can carry several invoices,
  // and each one deserves its own row - so Select PDF Binary fans this list out
  // into one item per PDF.
  const pdfAttachments = [];
  const attachmentNames = [];

  for (const key of Object.keys(binary)) {
    const b = binary[key] || {};
    const name = String(b.fileName || '');
    if (name) attachmentNames.push(name);
    const isPdf =
      b.mimeType === 'application/pdf' || name.toLowerCase().endsWith('.pdf');
    if (isPdf) pdfAttachments.push({ key, name });
  }

  const hasPdfAttachment = pdfAttachments.length > 0;
  const hasAttachment = attachmentNames.length > 0;

  // Deliberately loose: anything with an attachment or an invoice-ish keyword is a
  // candidate. Telling a real invoice from a look-alike is Claude's job downstream,
  // because keywords alone cannot separate "your invoice" from "invoicing moves to
  // the new portal". This only exists to avoid spending an API call on every email.
  const isCandidate =
    hasAttachment || KEYWORDS.test(subject) || KEYWORDS.test(emailBody);

  out.push({
    json: {
      gmail_message_id: gmailMessageId,
      received_date: toIso(j.date),
      subject,
      sender_email: senderEmail,
      email_body: emailBody,
      has_pdf_attachment: hasPdfAttachment,
      has_attachment: hasAttachment,
      pdf_attachments: pdfAttachments,
      pdf_count: pdfAttachments.length,
      attachment_names: attachmentNames.join(', '),
      is_candidate: isCandidate,
    },
    binary,
  });
}

return out;

// Node: "Select PDF Binary"  (Code, Run Once for All Items)
//
// Fans one email out into one item per PDF attachment, because a single email can
// carry several invoices and each one needs its own row.
//
// It also renames the chosen attachment to a fixed binary key. Gmail names
// attachments attachment_0, attachment_1, ... but Extract From File reads one
// fixed property, so the PDF being processed is always copied to "data".
//
// Emitting N items here is what makes the rest of the PDF path work unchanged:
// Extract From File runs once per item, and Check PDF Text realigns the email
// context by index against this node's output.

const out = [];

for (const item of $input.all()) {
  const list = Array.isArray(item.json.pdf_attachments) ? item.json.pdf_attachments : [];

  for (let i = 0; i < list.length; i++) {
    const att = list[i] || {};
    const binary = {};
    if (att.key && item.binary && item.binary[att.key]) {
      binary.data = item.binary[att.key];
    }

    out.push({
      json: {
        ...item.json,
        pdf_binary_key: att.key,
        pdf_file_name: att.name || '',
        pdf_index: i + 1,
        pdf_count: list.length,
      },
      binary,
    });
  }
}

return out;

// Node: "Check PDF Text"  (Code, Run Once for All Items)
//
// Decides whether the PDF gave us text worth sending to Claude, and re-attaches
// the email context.
//
// The context has to be recovered rather than read off the incoming item, because
// Extract From File does not carry it through reliably:
//   - on success it merges item.json ONLY when keepSource is set; the guard is a
//     truthiness test (`options.keepSource && ... !== 'binary'`), so an unset
//     option silently discards everything upstream;
//   - on failure its catch block emits `{ error }` on its own, discarding json
//     outright no matter what keepSource says.
// Recovering by index from "Select PDF Binary" covers both, since Extract From
// File pushes exactly one item per input item, in order, from both its try and
// its catch branch.
//
// Two failure modes are caught here and neither is sent to Claude:
//   - the node threw            -> a corrupt or unopenable file
//   - it opened but has no text -> a flat scan with no text layer
// Handing a model an empty or near-empty string invites a confident invented
// answer, which is worse than an honest failure. OCR is out of scope, and the
// note says so.

const sources = $('Select PDF Binary').all();
const results = $input.all();

// A genuine invoice page carries hundreds of alphanumeric characters. A scan
// with no text layer carries none, or a few stray artefacts. Both thresholds
// have to fail for the text to be rejected on density grounds.
const MIN_USABLE_CHARS = 40;
const MIN_ALNUM_PER_PAGE = 60;

// "Print to PDF" from a browser stamps a header and footer onto the page: a
// timestamp, the document title, the source URL and a page marker. When someone
// prints a screenshot of an invoice, THAT CHROME IS THE ONLY REAL TEXT IN THE
// FILE - the invoice itself is a flat image. It is enough to clear a naive
// character count, which is how such a file reaches the model and comes back
// classified on the strength of a URL. Strip the chrome first, then measure what
// is genuinely left. Removing a stray URL from a real invoice costs nothing,
// because a real invoice has hundreds of characters besides.
function stripPrintChrome(input) {
  return String(input || '')
    // print timestamp: "7/28/25, 4:53 PM" or "28/07/2025, 16:53"
    .replace(/\b\d{1,2}\/\d{1,2}\/\d{2,4},?\s*\d{1,2}:\d{2}(?::\d{2})?\s*(?:AM|PM)?/gi, ' ')
    // source URL in the footer
    .replace(/https?:\/\/\S+/gi, ' ')
    // image dimension annotation: "(620×877)"
    .replace(/\(\s*\d{2,5}\s*[×x]\s*\d{2,5}\s*\)/gi, ' ')
    // bare asset filename used as the print title
    .replace(/\b[\w.-]+\.(?:webp|png|jpe?g|gif|bmp|tiff?|svg|pdf|html?)\b/gi, ' ')
    // page marker "1/1" - the lookarounds keep it from eating a date like 08/12/2026
    .replace(/(?<![\d/])\d{1,3}\s*\/\s*\d{1,3}(?![\d/])/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Belt and braces: take each context field from the merged json when keepSource
// did its job, and fall back to the indexed source item otherwise. Either
// mechanism alone is sufficient, so a regression in one does not blank the row.
const pick = (a, b, key) => (a[key] !== undefined && a[key] !== '' ? a[key] : b[key]) || '';

const out = [];

for (let i = 0; i < results.length; i++) {
  const src = (sources[i] && sources[i].json) || {};
  const j = (results[i] && results[i].json) || {};

  const rawError = j.error;
  const errorMessage = rawError
    ? typeof rawError === 'string'
      ? rawError
      : rawError.message || 'PDF extraction failed'
    : null;

  const text = String(j.text || '').trim();
  const pages = Math.max(1, Number(j.numpages) || 1);

  // Measure the content, not the browser's print header and footer.
  const content = stripPrintChrome(text);
  const alnum = (content.match(/[A-Za-z0-9]/g) || []).length;
  const alnumPerPage = alnum / pages;
  const chromeOnly = text.length > 0 && alnum < MIN_USABLE_CHARS;

  let textUsable = true;
  let unreadableReason = '';

  if (errorMessage) {
    textUsable = false;
    unreadableReason =
      'PDF could not be opened (file is corrupt or not a readable PDF): ' + errorMessage;
  } else if (content.length < MIN_USABLE_CHARS || alnum < MIN_USABLE_CHARS) {
    textUsable = false;
    unreadableReason =
      'PDF opened (' + pages + ' page(s)) but carries no readable invoice text' +
      (chromeOnly
        ? ' - the only text in the file is the browser print header/footer (timestamp, title, source URL), so the invoice itself is a flat image'
        : '') +
      ' (' + text.length + ' characters extracted, ' + alnum +
      ' alphanumeric once print chrome is removed). OCR is not supported by this workflow, ' +
      'so nothing was guessed.';
  } else if (alnumPerPage < MIN_ALNUM_PER_PAGE) {
    textUsable = false;
    unreadableReason =
      'PDF opened (' + pages + ' page(s)) but the extracted text is too sparse to be a real ' +
      'invoice (' + alnum + ' alphanumeric characters, ' + Math.round(alnumPerPage) +
      ' per page) - most likely scanner artefacts over a flat image. OCR is not supported by ' +
      'this workflow, so nothing was guessed.';
  }

  out.push({
    json: {
      gmail_message_id: pick(j, src, 'gmail_message_id'),
      received_date: pick(j, src, 'received_date'),
      subject: pick(j, src, 'subject'),
      sender_email: pick(j, src, 'sender_email'),
      source_type: 'pdf_attachment',
      file_reference: pick(j, src, 'pdf_file_name'),
      pdf_index: src.pdf_index || 1,
      pdf_count: src.pdf_count || 1,
      // Claude still receives the original text; the chrome is harmless noise to
      // a model and could occasionally carry a real clue. Only the GATE runs on
      // the stripped version.
      invoice_text: text,
      text_chars: text.length,
      text_alnum: alnum,
      text_content_chars: content.length,
      pdf_pages: pages,
      text_usable: textUsable,
      unreadable_reason: unreadableReason,
    },
  });
}

return out;

// Node: "Use Email Body"  (Code, Run Once for All Items)
// No PDF attachment: the email body itself is the invoice source.

const MIN_USABLE_CHARS = 20;

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const text = String(j.email_body || '').trim();
  const usable = text.length >= MIN_USABLE_CHARS;

  out.push({
    json: {
      gmail_message_id: j.gmail_message_id,
      received_date: j.received_date,
      subject: j.subject,
      sender_email: j.sender_email,
      source_type: 'email_body',
      // If there were attachments but none were PDFs, name them so the log shows
      // why the body was used instead.
      file_reference: j.has_attachment && !j.has_pdf_attachment ? j.attachment_names : '',
      invoice_text: text,
      text_usable: usable,
      unreadable_reason: usable
        ? ''
        : 'Email body was empty or too short to contain invoice details, and no readable PDF was attached.',
    },
  });
}

return out;

// Node: "Prepare For Claude"  (Code, Run Once for All Items)
// Builds the full Anthropic request body here rather than inside the HTTP node,
// so the prompt is version-controlled, testable, and the HTTP node stays trivial
// (its JSON body is just  {{ JSON.stringify($json.claude_request) }} ).
//
// tool_choice pins the model to a single tool, so the reply is always a
// structured object - there is no prose to regex out and nothing to "parse
// loosely". The schema marks every field required, so the model must decide
// explicitly, and null is the only way to say "not present".

const SYSTEM_PROMPT = [
  'You extract invoice data for Novus Realty, a property management company.',
  'You are given the raw text of one email - either the email body, or text extracted from a PDF attachment.',
  '',
  'First decide whether the text is genuinely an invoice, bill, or fee note requesting payment for goods or services already identified.',
  'Then call the record_invoice tool.',
  '',
  'Rules, in order of importance:',
  '1. Never invent, guess, infer, or estimate a value that is not explicitly present in the text. If a field is absent or ambiguous, return null for it. A blank field is correct and useful; a plausible-looking invented one is a serious error, because nothing downstream can tell it apart from a real value.',
  '2. Set is_invoice to false, and every other field to null, when the text is not an actual invoice. Examples that are NOT invoices: a reminder to update a saved payment method, a newsletter or internal update that merely mentions invoicing or billing, a receipt confirming a payment already made, a quote or estimate, a delivery note.',
  '3. total_amount must be the final total payable, as a plain number: no currency symbol, no thousands separators, no text. If several totals appear (subtotal, tax, total), return the final gross total.',
  '4. currency must be a three-letter ISO 4217 code (USD, EUR, GBP, ...). Derive it only from an explicit symbol, code, or word in the text. If the text shows an ambiguous symbol with no other clue, return null rather than assuming.',
  '5. Dates must be YYYY-MM-DD. Interpret them using the invoice\'s own conventions and language - note that in European layouts DD/MM/YYYY is normal, so 08/12/2026 is 8 December 2026, not 12 August. If you cannot determine a date with confidence, return null.',
  '6. invoice_number is the vendor\'s own reference for the invoice. Do not substitute an account number, a customer number, a VAT/tax number, an order number, or a payment reference. If the document carries no invoice number of its own, return null.',
  '7. vendor_name is the party issuing the invoice and being paid, not Novus Realty (the recipient).',
  '8. description is a short summary of what is being billed, in English, at most about 200 characters.',
  '9. The text may be in a language other than English, or bilingual. Extract the values regardless of language.',
].join('\n');

const TOOL = {
  name: 'record_invoice',
  description:
    'Record the invoice fields extracted from the text, or report that the text is not an invoice.',
  input_schema: {
    type: 'object',
    properties: {
      is_invoice: {
        type: 'boolean',
        description: 'True only if this text is an actual invoice, bill, or fee note requesting payment.',
      },
      vendor_name: { type: ['string', 'null'], description: 'The party issuing the invoice.' },
      invoice_number: { type: ['string', 'null'], description: "The vendor's own invoice reference, or null." },
      invoice_date: { type: ['string', 'null'], description: 'Issue date as YYYY-MM-DD, or null.' },
      due_date: { type: ['string', 'null'], description: 'Payment due date as YYYY-MM-DD, or null.' },
      total_amount: { type: ['number', 'null'], description: 'Final total payable as a plain number, or null.' },
      currency: { type: ['string', 'null'], description: 'ISO 4217 three-letter code, or null.' },
      description: { type: ['string', 'null'], description: 'Short summary of what is billed, or null.' },
    },
    required: [
      'is_invoice',
      'vendor_name',
      'invoice_number',
      'invoice_date',
      'due_date',
      'total_amount',
      'currency',
      'description',
    ],
  },
};

// Guard against a pathological attachment blowing up the request.
const MAX_TEXT_CHARS = 24000;

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  let text = String(j.invoice_text || '');
  let truncated = false;

  if (text.length > MAX_TEXT_CHARS) {
    text = text.slice(0, MAX_TEXT_CHARS);
    truncated = true;
  }

  const userContent = [
    'Source: ' + (j.source_type === 'pdf_attachment' ? 'text extracted from a PDF attachment' : 'the email body'),
    'Email subject: ' + (j.subject || '(none)'),
    'Sender: ' + (j.sender_email || '(unknown)'),
    '',
    '--- BEGIN TEXT ---',
    text,
    '--- END TEXT ---',
  ].join('\n');

  out.push({
    json: {
      ...j,
      text_truncated: truncated,
      claude_request: {
        // NOTE: do not add temperature / top_p / top_k here. Sampling parameters
        // are removed on Claude Sonnet 5 and the API rejects them with a 400
        // ("`temperature` is deprecated for this model").
        model: 'claude-sonnet-5',
        max_tokens: 1024,
        system: SYSTEM_PROMPT,
        tools: [TOOL],
        tool_choice: { type: 'tool', name: 'record_invoice' },
        messages: [{ role: 'user', content: userContent }],
      },
    },
  });
}

return out;

// Node: "Parse Claude Response"  (Code, Run Once for All Items)
//
// IMPORTANT: the HTTP Request node REPLACES item.json with the API response, so
// gmail_message_id / sender_email / source_type / file_reference are gone by the
// time we get here. They are recovered by index from "Prepare For Claude", which
// is safe because HTTP Request emits exactly one output item per input item, in
// order - including when a call fails and onError=continueRegularOutput turns it
// into an error item. (Deliberately not using itemMatching(), whose paired-item
// resolution is fragile across an HTTP node.)

const contextItems = $('Prepare For Claude').all();
const responses = $input.all();

const out = [];

for (let i = 0; i < responses.length; i++) {
  const ctx = (contextItems[i] && contextItems[i].json) || {};
  const res = (responses[i] && responses[i].json) || {};

  const base = {
    gmail_message_id: ctx.gmail_message_id,
    received_date: ctx.received_date,
    subject: ctx.subject,
    sender_email: ctx.sender_email,
    source_type: ctx.source_type,
    file_reference: ctx.file_reference,
  };

  // 1. Did the HTTP call itself fail?
  if (res.error) {
    const msg =
      typeof res.error === 'string'
        ? res.error
        : res.error.message || JSON.stringify(res.error).slice(0, 300);
    out.push({ json: { ...base, _outcome: 'api_error', _error: 'Claude API call failed: ' + msg, keep_processing: true } });
    continue;
  }

  // 2. Did the API return an error payload with a 200-shaped body?
  if (res.type === 'error') {
    const msg = (res.error && res.error.message) || 'unknown API error';
    out.push({ json: { ...base, _outcome: 'api_error', _error: 'Claude API returned an error: ' + msg, keep_processing: true } });
    continue;
  }

  // 3. Find the forced tool call.
  const content = Array.isArray(res.content) ? res.content : [];
  const toolBlock = content.find(
    (b) => b && b.type === 'tool_use' && b.name === 'record_invoice',
  );

  if (!toolBlock || !toolBlock.input) {
    out.push({
      json: {
        ...base,
        _outcome: 'api_error',
        keep_processing: true,
        _error:
          'Claude did not return a record_invoice tool call (stop_reason: ' +
          (res.stop_reason || 'unknown') +
          ').',
      },
    });
    continue;
  }

  const f = toolBlock.input;

  out.push({
    json: {
      ...base,
      _outcome: 'extracted',
      _error: '',
      is_invoice: f.is_invoice === true,
      // Only an actual invoice goes on to be validated and logged. A failure to
      // process still continues, because the brief asks for those to be recorded
      // with enough detail to debug later.
      keep_processing: f.is_invoice === true,
      vendor_name: f.vendor_name,
      invoice_number: f.invoice_number,
      invoice_date: f.invoice_date,
      due_date: f.due_date,
      total_amount: f.total_amount,
      currency: f.currency,
      description: f.description,
      text_truncated: ctx.text_truncated === true,
    },
  });
}

return out;

// Node: "Build Unreadable Row"  (Code, Run Once for All Items)
// The false branch of "Text Usable?": a corrupt PDF, a scan with no text layer,
// or an empty body. Claude is never called. The row records why, so the failure
// is visible in the sheet instead of only in an n8n execution log.

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  out.push({
    json: {
      gmail_message_id: j.gmail_message_id,
      received_date: j.received_date,
      subject: j.subject,
      sender_email: j.sender_email,
      source_type: j.source_type,
      file_reference: j.file_reference,
      _outcome: 'unreadable',
      keep_processing: true,
      _error: j.unreadable_reason || 'Invoice text could not be read.',
    },
  });
}

return out;

// Node: "Finalize Row"  (Code, Run Once for All Items)
//
// Single convergence point. Both the Claude path and the unreadable path arrive
// here, and exactly one row shape leaves - the 15 columns of the sheet, in order.
// Validation happens here too: it FLAGS problems, it never blocks or backfills.
// A missing field stays blank and is named in error_note, because a blank cell is
// honest and an invented value is not.

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
const ISO_CURRENCY = /^[A-Z]{3}$/;

function cleanText(v) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  // Guard against a model that answers with a literal placeholder instead of null.
  if (/^(null|n\/a|na|none|unknown|not specified|not provided|-)$/i.test(s)) return '';
  return s;
}

function isRealDate(s) {
  if (!ISO_DATE.test(s)) return false;
  const [y, m, d] = s.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return (
    dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d
  );
}

const EMPTY_ROW = {
  vendor_name: '',
  invoice_number: '',
  invoice_date: '',
  due_date: '',
  total_amount: '',
  currency: '',
  description: '',
};

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const base = {
    received_date: j.received_date || '',
    sender_email: j.sender_email || '',
    subject: j.subject || '',
    source_type: j.source_type || '',
    file_reference: j.file_reference || '',
    processed_at: new Date().toISOString(),
  };

  // --- Paths that never produced invoice fields -----------------------------
  if (j._outcome === 'unreadable') {
    out.push({
      json: { ...base, ...EMPTY_ROW, processing_status: 'unsupported_attachment', error_note: j._error },
    });
    continue;
  }

  if (j._outcome === 'api_error') {
    out.push({
      json: { ...base, ...EMPTY_ROW, processing_status: 'extraction_failed', error_note: j._error },
    });
    continue;
  }

  // --- Claude classified it as not an invoice -------------------------------
  if (j.is_invoice !== true) {
    out.push({
      json: {
        ...base,
        ...EMPTY_ROW,
        processing_status: 'not_invoice',
        error_note:
          'Matched an invoice keyword or carried an attachment, but Claude classified the content as not an invoice. No fields were extracted.',
      },
    });
    continue;
  }

  // --- Normalise the extracted fields ---------------------------------------
  const vendorName = cleanText(j.vendor_name);
  const invoiceNumber = cleanText(j.invoice_number);
  const description = cleanText(j.description);

  const rawCurrency = cleanText(j.currency).toUpperCase();
  const currency = ISO_CURRENCY.test(rawCurrency) ? rawCurrency : '';

  const rawInvoiceDate = cleanText(j.invoice_date);
  const invoiceDate = isRealDate(rawInvoiceDate) ? rawInvoiceDate : '';

  const rawDueDate = cleanText(j.due_date);
  const dueDate = isRealDate(rawDueDate) ? rawDueDate : '';

  let totalAmount = '';
  if (typeof j.total_amount === 'number' && isFinite(j.total_amount)) {
    totalAmount = j.total_amount;
  } else if (j.total_amount !== null && j.total_amount !== undefined) {
    // Defensive: accept a numeric string, reject anything else.
    const n = Number(String(j.total_amount).replace(/[^0-9.\-]/g, ''));
    if (String(j.total_amount).trim() !== '' && isFinite(n)) totalAmount = n;
  }

  // --- Validate: report, do not repair --------------------------------------
  const missing = [];
  const invalid = [];

  if (!vendorName) missing.push('vendor_name');
  if (!invoiceNumber) missing.push('invoice_number');
  if (totalAmount === '') missing.push('total_amount');
  else if (typeof totalAmount === 'number' && totalAmount <= 0) invalid.push('total_amount is not positive');
  if (!currency) {
    if (rawCurrency) invalid.push('currency "' + rawCurrency + '" is not a valid ISO 4217 code');
    else missing.push('currency');
  }
  if (!invoiceDate && !dueDate) missing.push('invoice_date or due_date');
  if (rawInvoiceDate && !invoiceDate) invalid.push('invoice_date "' + rawInvoiceDate + '" is not a valid YYYY-MM-DD date');
  if (rawDueDate && !dueDate) invalid.push('due_date "' + rawDueDate + '" is not a valid YYYY-MM-DD date');

  const notes = [];
  if (missing.length) notes.push('Missing: ' + missing.join(', ') + '.');
  if (invalid.length) notes.push('Invalid: ' + invalid.join('; ') + '.');
  if (j.text_truncated) notes.push('Source text was truncated before extraction.');

  out.push({
    json: {
      ...base,
      vendor_name: vendorName,
      invoice_number: invoiceNumber,
      invoice_date: invoiceDate,
      due_date: dueDate,
      total_amount: totalAmount,
      currency,
      description,
      processing_status: missing.length || invalid.length ? 'valid_missing_fields' : 'valid',
      error_note: notes.join(' '),
    },
  });
}

return out;

// Node: "Check Duplicate"  (Code, Run Once for All Items)
//
// IMPORTANT: a Google Sheets read REPLACES the incoming items with sheet rows, so
// $input.all() here is the SHEET, not the invoice. The invoice rows are taken
// from "Finalize Row" by node reference. (Getting this wrong silently compares
// the sheet against itself and lets every duplicate through.)
//
// "Get All Rows" has Always Output Data on, so an empty sheet still emits one
// bare item rather than halting the workflow. Genuine sheet rows always carry
// row_number, which is how that placeholder is told apart from real data.
//
// IDENTITY
// --------
// A row is identified by four fields together:
//
//     total_amount | invoice_number | sender_email | file_reference
//
// That combination is what makes a document unique in practice. It deliberately
// does NOT use the Gmail message id: a resent invoice arrives as a brand-new
// message, so keying on the message would treat every resend as new. Keying on
// the document instead means a resend is recognised however it arrives, while a
// re-processed execution still resolves to the same key.
//
// Where one email carries several PDFs, each becomes its own row, and the file
// name is what keeps them apart.

const sheetRows = $input
  .all()
  .map((r) => r.json || {})
  .filter((r) => r.row_number !== undefined && r.row_number !== null);

const invoices = $('Finalize Row').all();

const norm = (v) => String(v === null || v === undefined ? '' : v).trim().toLowerCase();

// Amounts must compare by value, not by how they were written: the sheet can hand
// back "1200" where the workflow produced 1200.0, or "1,200.50" if a human edited
// the cell. Anything that is not a number falls back to plain text comparison.
function normAmount(v) {
  const raw = norm(v);
  if (raw === '') return '';
  if (!/\d/.test(raw)) return raw;
  const n = Number(raw.replace(/[^0-9.\-]/g, ''));
  return isFinite(n) ? String(n) : raw;
}

const identity = (r) =>
  [normAmount(r.total_amount), norm(r.invoice_number), norm(r.sender_email), norm(r.file_reference)].join('|');

const out = [];

for (const item of invoices) {
  const j = item.json || {};
  const key = identity(j);

  // A failure logged from an email body has no number, no total and no file, so
  // the composite key collapses to the sender alone - which would make two
  // unrelated failures from one vendor look identical. Those rows, and only
  // those, fall back to matching on the subject.
  const keyIsThin =
    !norm(j.invoice_number) && normAmount(j.total_amount) === '' && !norm(j.file_reference);

  let isDuplicate = false;
  let duplicateReason = '';

  for (const row of sheetRows) {
    if (!keyIsThin) {
      if (identity(row) === key) {
        isDuplicate = true;
        duplicateReason = 'same total, invoice number, sender and file as row ' + row.row_number;
        break;
      }
    } else if (
      j.subject &&
      norm(row.subject) === norm(j.subject) &&
      norm(row.sender_email) === norm(j.sender_email) &&
      !norm(row.invoice_number) &&
      !norm(row.file_reference)
    ) {
      isDuplicate = true;
      duplicateReason =
        'same subject and sender as row ' + row.row_number +
        ', with no invoice number, total or attachment to tell them apart';
      break;
    }
  }

  out.push({
    json: {
      ...j,
      is_duplicate: isDuplicate,
      duplicate_reason: duplicateReason,
      duplicate_key: key,
      sheet_rows_checked: sheetRows.length,
    },
  });
}

return out;

// Node: "Build Sheet Row"  (Code, Run Once for All Items)
// Emits exactly the sheet's columns, in order, and nothing else. The duplicate
// check adds bookkeeping fields (is_duplicate, duplicate_reason, ...) that must
// not reach the Append node, because "Map Automatically" maps whatever it is
// given by name. This node is the contract with the spreadsheet.

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  out.push({
    json: {
      received_date: j.received_date || '',
      // subject identifies a row whose invoice fields are all blank, and is what
      // the last-resort duplicate rule matches on.
      subject: j.subject || '',
      vendor_name: j.vendor_name || '',
      sender_email: j.sender_email || '',
      invoice_number: j.invoice_number || '',
      invoice_date: j.invoice_date || '',
      due_date: j.due_date || '',
      total_amount: j.total_amount === '' || j.total_amount === null || j.total_amount === undefined ? '' : j.total_amount,
      currency: j.currency || '',
      description: j.description || '',
      source_type: j.source_type || '',
      file_reference: j.file_reference || '',
      processing_status: j.processing_status || '',
      error_note: j.error_note || '',
      processed_at: j.processed_at || new Date().toISOString(),
    },
  });
}

return out;
